const QS = [
{id:1,d:1,q:"Which application is available to ALL users by default in ServiceNow?",opts:["Change", "Incident", "Facilities", "Self Service"],ans:[3],multi:false,src:"course",exp:"Self Service is the only default app for all users"},
{id:2,d:1,q:"Which module displays tasks assigned to a user's group but NOT yet assigned to an individual?",opts:["My Teams Work", "My Groups Work", "My Groups Tasks", "My Teams Tasks"],ans:[1],multi:false,src:"course",exp:"My Groups Work = group queue not yet assigned to an individual"},
{id:3,d:1,q:"What is the Application Navigator used for?",opts:["Tracking the history of record changes", "Accessing all installed applications and their modules", "Defining workflow routing logic", "Managing database table schemas"],ans:[1],multi:false,src:"course",exp:"Application Navigator = left sidebar for all apps/modules"},
{id:4,d:1,q:"A user wants to return quickly to a frequently used module without searching. Which feature should they use?",opts:["System Properties", "Favorites (starred items)", "The search bar only", "Update Set history"],ans:[1],multi:false,src:"course",exp:"Favorites = bookmarks for quick navigation"},
{id:5,d:1,q:"In Next Experience Unified Navigation, where does a user set personal preferences such as time zone, language, and theme?",opts:["System Properties > User Preferences", "User Administration > User Profile", "The Profile menu (avatar/name in the top-right corner)", "System Settings > Global"],ans:[2],multi:false,src:"course",exp:"Profile menu = personal preferences"},
{id:6,d:1,q:"What is the Service Portal in ServiceNow?",opts:["An admin portal for managing plugins and Update Sets", "A consumer-friendly web interface for end users to submit requests, search knowledge, and track tickets — separate from the backend admin UI", "A reporting portal for compliance dashboards", "A portal used exclusively for change management approvals"],ans:[1],multi:false,src:"course",exp:"Service Portal = self-service front end for end users"},
{id:7,d:1,q:"Where can a user find recently viewed records in the Next Experience UI?",opts:["Application menu", "Favorites", "History / Recent module", "System Log"],ans:[2],multi:false,src:"course",exp:"History/Recent = recently viewed records"},
{id:8,d:1,q:"Which of the following are typical starting points for navigation in the Next Experience UI?",opts:["Type a table name or module name in the Application Navigator filter text box", "Use a direct instance URL with a /nav_to.do?uri= reference", "Edit global.js in the customer instance files", "SSH into the instance and edit index.html"],ans:[0, 1],multi:true,src:"course",exp:"Filter text + direct URL are the two nav starting points"},
{id:9,d:2,q:"What is a Plugin in ServiceNow?",opts:["An optional feature or application activated via the Plugin Manager to extend platform functionality", "A third-party JavaScript library embedded in a client script", "A MID Server extension for protocol translation", "A widget added to the Service Portal"],ans:[0],multi:false,src:"course",exp:"Plugin = optional feature activated via Plugin Manager"},
{id:10,d:2,q:"Why would an administrator install a plugin on a ServiceNow instance?",opts:["To patch the underlying operating system", "To add new platform capabilities such as HR, ITSM, or SecOps functionality", "To connect to third-party email providers only", "To safely delete system properties"],ans:[1],multi:false,src:"course",exp:"Plugins extend the platform with new tables, logic, and UX"},
{id:11,d:2,q:"What is the purpose of System Properties (sys_properties)?",opts:["Read-only metadata about the current platform version", "Global key-value configuration settings that control platform and application behavior without code changes", "A log of all system events for audit purposes", "The definition of field types in the database dictionary"],ans:[1],multi:false,src:"course",exp:"System Properties = global key-value config settings"},
{id:12,d:2,q:"A ServiceNow admin wants to copy the production instance's data and configuration onto a development instance. What is this process called?",opts:["Export/Import via Update Sets", "Instance Cloning", "Data Migration via Import Sets", "Plugin synchronization"],ans:[1],multi:false,src:"course",exp:"Cloning = copy one instance onto another"},
{id:13,d:2,q:"What is a MID Server?",opts:["A secondary ServiceNow instance used for load balancing", "A Java application installed on a customer's on-premises network that allows the cloud instance to communicate with resources behind the firewall", "A caching layer between the browser and the ServiceNow instance", "A middleware server that converts REST calls to SOAP"],ans:[1],multi:false,src:"course",exp:"MID Server = on-prem Java agent bridging cloud to LAN"},
{id:14,d:2,q:"Which plugin or application would enable HR Service Delivery capabilities on an instance?",opts:["Customer Service Management", "HR Service Delivery", "Financial Services Operations", "IT Asset Management"],ans:[1],multi:false,src:"course",exp:"HR Service Delivery is its own plugin/application"},
{id:15,d:2,q:"Which interface is best for adding UI text and widgets without writing code?",opts:["Scripted REST API", "UI Scripts (raw JS only)", "UI Builder / low-code interface", "MID Server terminal"],ans:[2],multi:false,src:"course",exp:"UI Builder = no-code interface for UI components"},
{id:16,d:2,q:"A user wants to personalize which columns appear in their list view. What feature allows this?",opts:["Form Designer", "List Personalization (gear icon or right-click column header)", "Dictionary Override", "System Properties"],ans:[1],multi:false,src:"course",exp:"List Personalization = per-user column customization"},
{id:17,d:2,q:"Which of the following can be personalized per user in the platform?",opts:["Homepage dashboard layout", "Browser network stack settings", "Time zone and language on My Profile", "Linux kernel parameters"],ans:[0, 2],multi:true,src:"course",exp:"Homepage and profile settings are user-personalizable"},
{id:18,d:2,q:"What setting path is used when configuring application-specific instance behavior?",opts:["Version Control menu on the form header", "Application Properties or System Properties", "Browser developer console", "Command-line launcher only"],ans:[1],multi:false,src:"course",exp:"Application Properties or System Properties"},
{id:19,d:3,q:"What does the breadcrumb filter at the top of a ServiceNow list do?",opts:["Shows the navigation path (app > module) for back-navigation", "Displays active filter conditions applied to the list and allows quick removal of individual conditions", "Defines which columns are shown", "Indicates which Update Set last modified the records"],ans:[1],multi:false,src:"course",exp:"Breadcrumb = active filter conditions, removable chips"},
{id:20,d:3,q:"What does \"grouping\" records in a list do?",opts:["Merges duplicate records into one", "Organizes list rows into collapsible sections based on a chosen field value", "Applies a permanent mandatory filter", "Exports records grouped by field to a CSV report"],ans:[1],multi:false,src:"course",exp:"Grouping = collapsible sections by field value"},
{id:21,d:3,q:"What is a View on a ServiceNow form?",opts:["A saved filter condition for a list", "A specific arrangement of fields on a form designed for a particular role or context", "A dashboard tab combining multiple reports", "A read-only snapshot of a record at a specific point in time"],ans:[1],multi:false,src:"course",exp:"View = field arrangement for a specific role/context"},
{id:22,d:3,q:"What is a Form Template used for?",opts:["Designing the visual layout of a dashboard", "Pre-populating a new record's fields with saved default values to speed up data entry", "Creating a reusable workflow stage", "Defining required fields for import sets"],ans:[1],multi:false,src:"course",exp:"Form Template = saved field defaults for faster data entry"},
{id:23,d:3,q:"What is the purpose of Tags in ServiceNow?",opts:["Labels that can be applied to records to help users organize and find related records across different tables", "Labels that mark fields as mandatory", "System-defined categories used in the Service Catalog", "Metadata markers applied to Update Set records"],ans:[0],multi:false,src:"course",exp:"Tags = cross-table labels for organizing records"},
{id:24,d:3,q:"What is a reference qualifier used for?",opts:["Changing database collation settings", "Restricting the values that appear in a reference field dropdown based on defined conditions", "Increasing plugin memory allocation", "Adding custom page headers to forms"],ans:[1],multi:false,src:"course",exp:"Reference qualifier = restricts values in reference field dropdown"},
{id:25,d:3,q:"Which form section behavior hides content from view while keeping it on the record?",opts:["Collapsible section", "Dictionary delete action", "Table truncation", "Audit field removal"],ans:[0],multi:false,src:"course",exp:"Collapsible section = hidden but still on the record"},
{id:26,d:3,q:"Which of the following best describes a Visual Task Board (VTB)?",opts:["A Kanban-style board for visualizing and managing tasks across lanes/stages", "A reporting dashboard that aggregates task metrics", "A form layout editor for task records", "A workflow diagram showing approval stages"],ans:[0],multi:false,src:"course",exp:"VTB = Kanban-style task board"},
{id:27,d:3,q:"What are the three types of Visual Task Boards?",opts:["Freeform — display any task type; members can manually add/remove cards and define lanes", "Flexible — filter-driven; cards removed automatically when tasks no longer match the filter; custom lanes allowed", "Guided — lanes correspond to a field's values (e.g., State) and cannot be manually edited", "Static — read-only snapshots of task states", "Report boards — generated directly from a PA indicator"],ans:[0, 1, 2],multi:true,src:"course",exp:"Three types: Freeform, Flexible, Guided"},
{id:28,d:3,q:"What is the difference between a Report and a Dashboard?",opts:["A report is a single data visualization; a dashboard aggregates multiple reports and widgets on one page", "Reports are admin-only; dashboards are available to all users", "Reports use only PA indicators; dashboards use only table queries", "Reports are scheduled; dashboards update in real time only"],ans:[0],multi:false,src:"course",exp:"Report = single viz; Dashboard = collection of visualizations"},
{id:29,d:3,q:"By default, who can see a report after it is created?",opts:["All users on the instance", "Only the report creator — it must be explicitly shared to be visible to others", "All users with the itil role", "All members of the creator's assignment group"],ans:[1],multi:false,src:"course",exp:"Reports are private by default"},
{id:30,d:3,q:"Which report type best shows the proportion of open incidents by category?",opts:["Time Series", "Gauge", "Pie / Donut chart", "Single Score"],ans:[2],multi:false,src:"course",exp:"Pie/Donut = proportion/distribution"},
{id:31,d:3,q:"What does Performance Analytics add beyond standard table reports?",opts:["Real-time streaming from external BI tools", "The ability to collect indicator data over time and track KPI trends historically; standard reports only show a point-in-time snapshot", "AI-powered narrative summaries", "Automated export to PowerPoint"],ans:[1],multi:false,src:"course",exp:"PA = historical trend data via collected indicators"},
{id:32,d:3,q:"A report shows duplicate rows for the same user. What should an admin check first?",opts:["User login session timeouts", "Duplicate active user records or duplicate entries in a reference field", "Plugin license expiration", "Kernel lock wait timeout"],ans:[1],multi:false,src:"course",exp:"Duplicate user records or duplicate reference field entries"},
{id:33,d:3,q:"What is an Email Notification in ServiceNow?",opts:["An automated email triggered by a defined record event or condition, sent to specified recipients", "An inbound action that converts incoming emails into records", "A scheduled batch email report sent to all admins", "A notification sent only when a record is manually flagged"],ans:[0],multi:false,src:"course",exp:"Email Notification = event-driven automated email"},
{id:34,d:3,q:"What is an Inbound Action used for?",opts:["Processing incoming emails to create or update records automatically", "Sending automated alerts to users based on threshold breaches", "Triggering a Flow Designer flow on a scheduled interval", "Importing external data via REST API"],ans:[0],multi:false,src:"course",exp:"Inbound Action = incoming email → create/update record"},
{id:35,d:3,q:"What are Work Notes vs Additional Comments on a task record?",opts:["Both are visible to all users including end customers", "Work Notes are internal (visible only to agents/fulfillment groups); Additional Comments are customer-facing", "Work Notes require manager approval; Additional Comments do not", "Work Notes are automatically sent by email; Additional Comments are not"],ans:[1],multi:false,src:"course",exp:"Work Notes = internal; Additional Comments = customer-visible"},
{id:36,d:3,q:"What is the purpose of an SLA (Service Level Agreement) on a task?",opts:["A time target commitment for response and/or resolution; triggers escalation actions when breached", "A role required to close an incident", "A catalog item type for requesting service agreements", "A business rule that fires when a task is assigned"],ans:[0],multi:false,src:"course",exp:"SLA = time target + escalation trigger on breach"},
{id:37,d:3,q:"Which best describes rota-based task assignment for a task queue?",opts:["Visual Task Board delegation rules only", "Assignment rules, workload management, or assignment groups", "Update Set merge operations on weekends", "Plugin disable/enable cycles"],ans:[1],multi:false,src:"course",exp:"Assignment rules/groups handle rota-based assignment"},
{id:38,d:3,q:"When should an admin avoid heavy email notifications for high-volume events?",opts:["When event management, in-app notifications, or webhooks are preferred to reduce email noise", "Only when the table contains no email field", "When browser-only routing is blocked", "Only when the MID Server is offline"],ans:[0],multi:false,src:"course",exp:"Event management/webhooks preferred for high-volume alerts"},
{id:39,d:3,q:"Which dashboard type is best suited for executive KPI review and trend tracking?",opts:["A terminal shell view", "A Performance Analytics or Platform Analytics dashboard", "A MID Server console dashboard", "A source code repository dashboard"],ans:[1],multi:false,src:"course",exp:"PA/Platform Analytics dashboard for KPI trends"},
{id:40,d:3,q:"Where are notification definitions configured for a given table?",opts:["MID Server network map", "System Notification > Email > Notifications", "Linux cron table", "Application Navigator > Logs"],ans:[1],multi:false,src:"course",exp:"System Notification > Email > Notifications"},
{id:41,d:4,q:"What is a Knowledge Base in ServiceNow used for?",opts:["Storing articles that help users and agents find answers without opening tickets", "Storing CI configuration data for the CMDB", "Reducing repeat incidents by deflecting users to self-service answers", "Automating approval routing for change requests"],ans:[0, 2],multi:true,src:"course",exp:"KB = self-service answers + incident deflection"},
{id:42,d:4,q:"Which knowledge article state allows end users to find and read the article?",opts:["Draft", "Published", "Retired", "Obsolete"],ans:[1],multi:false,src:"course",exp:"Published = visible to end users"},
{id:43,d:4,q:"Which role is typically required to publish a knowledge article?",opts:["admin", "knowledge or knowledge_admin", "itil", "catalog_admin"],ans:[1],multi:false,src:"course",exp:"knowledge or knowledge_admin role required"},
{id:44,d:4,q:"What controls which users can see a specific Knowledge Base or Service Catalog item?",opts:["ACL rules on the kb_knowledge table", "User Criteria", "Business Rules with role conditions", "System Properties"],ans:[1],multi:false,src:"course",exp:"User Criteria = visibility rules for KB and catalog"},
{id:45,d:4,q:"Which data structure supports nested categorization of knowledge articles?",opts:["Knowledge article text body only", "Knowledge categories hierarchy", "Virtual Agent intents", "Update Set lineage tree"],ans:[1],multi:false,src:"course",exp:"Knowledge categories hierarchy supports nested topics"},
{id:46,d:4,q:"In the Service Catalog, what is a Catalog Item?",opts:["A predefined offering (e.g., new laptop, software access) that end users can request", "A configuration record containing workflow routing logic", "A report showing pending fulfillment status", "A role granting access to submit requests"],ans:[0],multi:false,src:"course",exp:"Catalog Item = requestable offering"},
{id:47,d:4,q:"What record is created when a user submits a Service Catalog request?",opts:["An Incident (inc)", "A Request (sc_request) containing one or more Requested Items (sc_req_item)", "A Task (task) and a Change Request (change_request)", "A Problem (problem) and a Service Request (sc_task)"],ans:[1],multi:false,src:"course",exp:"sc_request (parent) + sc_req_item (one per item ordered)"},
{id:48,d:4,q:"Multiple Choice, Single Line Text, and Select Box are what type of element in ServiceNow?",opts:["Order Guides", "Request Types", "Variable Types", "Related Lists"],ans:[2],multi:false,src:"course",exp:"Variable Types = field types on catalog item request forms"},
{id:49,d:4,q:"What is an Order Guide in the Service Catalog?",opts:["A bundle of related catalog items ordered together as a package", "Step-by-step help text displayed when a user opens a catalog item", "The SLA definition for fulfillment time targets", "The approval chain definition for a catalog request"],ans:[0],multi:false,src:"course",exp:"Order Guide = bundled catalog items as a package"},
{id:50,d:4,q:"What is the difference between a Record Producer and a Catalog Item?",opts:["Both create only email notification templates", "Record Producers create records in any target table; standard Catalog Items generate sc_request/sc_req_item records", "Record Producers disable workflows on the target record", "Catalog Items are limited to read ACLs only"],ans:[1],multi:false,src:"course",exp:"Record Producer → any target table; Catalog Item → sc_request"},
{id:51,d:4,q:"How is the request workflow triggered when a user orders a catalog item?",opts:["Browser cron schedule", "The catalog item's associated flow or workflow activates on submission of the sc_request/sc_req_item", "MID Server scheduler", "Linux cron"],ans:[1],multi:false,src:"course",exp:"Flow/workflow fires on sc_req_item creation"},
{id:52,d:4,q:"In Flow Designer, what is the difference between a Flow and a Subflow?",opts:["A Flow is triggered by an event, schedule, or catalog item; a Subflow is a reusable logic component called from flows or other subflows", "Flows run client-side; Subflows run server-side", "Flows are limited to one application scope; Subflows are global only", "Flows require scripting; Subflows are no-code only"],ans:[0],multi:false,src:"course",exp:"Flow = triggered; Subflow = reusable component"},
{id:53,d:4,q:"Which of the following can trigger a Flow Designer flow?",opts:["A record being created or updated", "A scheduled date/time or recurring interval", "A MID Server heartbeat event", "A plugin being activated"],ans:[0, 1],multi:true,src:"course",exp:"Record triggers and scheduled triggers"},
{id:54,d:4,q:"A self-service flow needs to pause and wait for a manager's approval before continuing. Which pattern is standard in Flow Designer?",opts:["A busy-wait loop using gs.info()", "An Approval action / human approval activity step in the flow", "SQL sleep on the transaction table", "A client-side blocking script"],ans:[1],multi:false,src:"course",exp:"Approval action = standard pause-for-human-approval step"},
{id:55,d:4,q:"What is Virtual Agent in ServiceNow?",opts:["An AI-powered chatbot platform that provides user assistance through automated conversations, helping users get information and complete tasks without agent involvement", "A background automation that runs scripts on a schedule", "An agent desktop tool that suggests answers to live human agents", "A testing framework for validating flow automations"],ans:[0],multi:false,src:"course",exp:"Virtual Agent = AI chatbot for user self-service"},
{id:56,d:4,q:"Virtual Agent topics can be authored using which of the following?",opts:["Virtual Agent Designer (drag-and-drop graphical canvas)", "NLU (Natural Language Understanding) for intent recognition", "Import Sets to load conversation scripts from Excel", "Transform Maps to define conversation branching rules"],ans:[0, 1],multi:true,src:"course",exp:"VA Designer + NLU"},
{id:57,d:4,q:"When should Virtual Agent be preferred over a static knowledge article?",opts:["When conversational intent routing helps users find the right answer faster", "When the content must never be updated", "When guided form completion reduces user errors", "When the file must be attached as a binary"],ans:[0, 2],multi:true,src:"course",exp:"Conversational routing + guided forms"},
{id:58,d:4,q:"What does Virtual Agent \"deflection\" mean?",opts:["Routing a ticket to a different assignment group", "Resolving a user's issue through the chatbot so no human-agent ticket is created", "Redirecting a user from the Service Portal to the backend admin UI", "Moving a conversation from Virtual Agent to email"],ans:[1],multi:false,src:"course",exp:"Deflection = bot resolves, no ticket created"},
{id:59,d:5,q:"In ServiceNow, what is a Table?",opts:["A collection of records where each row is a record and each column is a field", "A grouping of workflow stages", "A container for Update Set configuration changes", "A form layout template"],ans:[0],multi:false,src:"course",exp:"Table = rows (records) + columns (fields)"},
{id:60,d:5,q:"Which table is the parent (base) for Incident, Problem, and Change Request?",opts:["sys_metadata", "cmdb_ci", "task", "sys_user"],ans:[2],multi:false,src:"course",exp:"task is the base parent for all task-type records"},
{id:61,d:5,q:"What does it mean for one table to extend another?",opts:["The child table inherits all fields from the parent and can add its own unique fields", "The child table copies the parent's records on a nightly schedule", "The child table's records replace the parent's records when deployed", "The child table only holds a foreign key reference to the parent"],ans:[0],multi:false,src:"course",exp:"Extending = inheritance; child gets all parent fields"},
{id:62,d:5,q:"Which object defines the schema (fields and their properties) of a table in ServiceNow?",opts:["Dictionary entry (sys_dictionary)", "Browser cache", "MID Server config file", "Update Set XML"],ans:[0],multi:false,src:"course",exp:"Dictionary entry = schema definition for each field"},
{id:63,d:5,q:"What is the sys_id of a record?",opts:["The display name field shown in reference dropdowns", "A globally unique identifier (GUID) automatically assigned to every record in every table", "The internal name of a table", "The primary key used only on the task table"],ans:[1],multi:false,src:"course",exp:"sys_id = GUID on every record in every table"},
{id:64,d:5,q:"Which field type stores a link to a record in another table and displays that record's display value?",opts:["String", "Integer", "Reference", "Choice"],ans:[2],multi:false,src:"course",exp:"Reference field = pointer to record in another table"},
{id:65,d:5,q:"What is a Dictionary Override used for?",opts:["Overriding an ACL rule for a specific application scope", "Renaming a table field in a specific language", "Changing the attributes of a field (e.g., making it mandatory) on a child/extended table without modifying the parent table definition", "Replacing a field's display value with a calculated value"],ans:[2],multi:false,src:"course",exp:"Dictionary Override = modify inherited field on child table only"},
{id:66,d:5,q:"What is an Access Control (ACL) rule used for?",opts:["Defining which roles can read, write, create, or delete records and fields in a table", "Encrypting data in transit between instances", "Scheduling which users can log in during specific hours", "Controlling which fields are exported in an Update Set"],ans:[0],multi:false,src:"course",exp:"ACL = read/write/create/delete access rules"},
{id:67,d:5,q:"In what order does the platform evaluate access controls on a record?",opts:["Table ACL rules first, then field ACL rules — and within each, most specific to most general", "Field ACL rules first, then table ACL rules", "All rules are evaluated at once and the first match wins", "Only one level of rule can exist per table"],ans:[0],multi:false,src:"docs",exp:"acl-rule-types.md: \"Match the object against table ACL rules. Match the object against field ACL rules... This processing order ensures that users gain access to more specific objects before gaining access to more general objects.\" Corrected — this question previously asked for \"most general to most specific\", which contradicted its own answer."},
{id:68,d:5,q:"A standard user cannot view a record they should be able to see. Which should an admin check first?",opts:["Reset the user's browser zoom", "Read ACL rules, roles assigned to the user, and any record-level conditions", "Replace the network router firmware", "Restart the MID Server"],ans:[1],multi:false,src:"course",exp:"Check Read ACL + roles + record conditions"},
{id:69,d:5,q:"A support engineer can view incidents but cannot create new ones. What is the most likely cause?",opts:["Browser zoom is too low", "Read ACL is allowing access, but write/create ACL is missing or denied for that role", "Linux file permission error on the instance", "The MID Server is offline"],ans:[1],multi:false,src:"course",exp:"Read ACL = allowed; write/create ACL = missing"},
{id:70,d:5,q:"What does the admin role grant in ServiceNow?",opts:["Read-only access to all tables for auditing", "Permission to manage user accounts and groups only", "Full unrestricted access to all platform features, tables, and configuration; admins can override ACLs", "Access limited to the Service Portal and self-service modules"],ans:[2],multi:false,src:"course",exp:"admin = full access, can override ACLs"},
{id:71,d:5,q:"How are roles typically granted to users?",opts:["Assigned directly on the user's record", "Inherited through membership in a group that has the role assigned", "Automatically assigned based on the user's department field value", "Deployed by running an Update Set on the production instance"],ans:[0, 1],multi:true,src:"course",exp:"Direct assignment or inherited via group"},
{id:72,d:5,q:"Why is separating user roles a security principle in ServiceNow?",opts:["It increases database size for audit trails", "It follows least privilege and separation of duties principles", "It increases network latency between instances", "It disables catalog widgets for standard users"],ans:[1],multi:false,src:"course",exp:"Least privilege + separation of duties"},
{id:73,d:5,q:"Which capability helps identify users with excess privileges?",opts:["MID Server connectivity test", "User access review and Access Control rule assessment (Access Analyzer)", "DNS cache flush", "Linux uptime report"],ans:[1],multi:false,src:"course",exp:"Access Analyzer = identifies excess privileges"},
{id:74,d:5,q:"What is the purpose of an Import Set in ServiceNow?",opts:["A staging table that holds data imported from an external source before it is transformed into a target ServiceNow table", "A container for moving configuration changes between instances", "A scheduled job that extracts CMDB data nightly", "A method for exporting records to an external system"],ans:[0],multi:false,src:"course",exp:"Import Set = staging table before transform"},
{id:75,d:5,q:"What is a Transform Map used for?",opts:["Converting Update Set XML from one format to another", "Translating UI labels into different languages", "Mapping CI relationships between CMDB classes", "Defining how each field in an Import Set table maps to a field in the target ServiceNow table"],ans:[3],multi:false,src:"course",exp:"Transform Map = field mapping staging → target table"},
{id:76,d:5,q:"What is a Coalesce field in a Transform Map?",opts:["A required field that must be present for a transform to execute", "A field that prevents duplicate records by matching incoming data against existing records using that field as a key", "A field that combines multiple source columns into one target field", "A field that triggers a post-transform business rule"],ans:[1],multi:false,src:"course",exp:"Coalesce = match key to prevent duplicate imports"},
{id:77,d:5,q:"Before importing a large data set, which step helps avoid bulk transform failures?",opts:["Convert the CSV to JPEG format first", "Define required fields, validate data format, and run a small test batch first", "Disable logging on the instance", "Rename the staging table"],ans:[1],multi:false,src:"course",exp:"Validate format + test batch before bulk import"},
{id:78,d:5,q:"When a data migration fails with duplicate key errors, what is the first thing to check?",opts:["Browser extension list", "Unique constraints in the target table and whether duplicate records already exist", "Instance memory allocation", "MID Server power cycle"],ans:[1],multi:false,src:"course",exp:"Check unique constraints + existing duplicate records"},
{id:79,d:5,q:"What is the CMDB used for in ServiceNow?",opts:["Storing and managing configuration items (CIs) and their relationships to support IT service management", "Staging imported data before transformation", "Archiving closed incident records for compliance", "Storing Update Set deployment history"],ans:[0],multi:false,src:"course",exp:"CMDB = authoritative CI inventory + relationships"},
{id:80,d:5,q:"Which of the following are examples of CI classes in the CMDB?",opts:["cmdb_ci_server (Server)", "sys_user (User)", "cmdb_ci_appl (Application)", "sc_request (Service Catalog Request)"],ans:[0, 2],multi:true,src:"course",exp:"cmdb_ci_server and cmdb_ci_appl are CI classes"},
{id:81,d:5,q:"What does CSDM stand for, and what is it used for?",opts:["Cloud Service Delivery Manager — a cloud cost optimization tool", "Common Service Data Model — a standard framework defining how business services, technical services, and CIs relate in the CMDB", "Control Server Device Mode — a MID Server configuration mode", "Client-Side Data Mirror — a caching layer for reference fields"],ans:[1],multi:false,src:"course",exp:"Common Service Data Model = standard framework for services/CIs"},
{id:82,d:5,q:"Which application supports automated CI population in the CMDB?",opts:["Browser developer console", "Discovery and Service Mapping", "Linux package manager", "Virtual Agent browser extension"],ans:[1],multi:false,src:"course",exp:"Discovery and Service Mapping populate the CMDB"},
{id:83,d:5,q:"What does CMDB reconciliation do?",opts:["Deletes all CI records older than 90 days", "Identifies and resolves duplicate or conflicting CI records from multiple data sources", "Increases network packet volume for CI discovery", "Controls Linux log rotation"],ans:[1],multi:false,src:"course",exp:"Reconciliation resolves duplicate/conflicting CI records"},
{id:84,d:5,q:"What is the Security Center (formerly Instance Security Center) used for?",opts:["A marketplace for approved security plugins", "A tool for scanning Update Sets for malicious scripts before commit", "A consolidated dashboard for monitoring instance security compliance, viewing security events, configuring hardening settings, and managing user sessions", "A report generator for PCI audit evidence only"],ans:[2],multi:false,src:"course",exp:"Security Center = compliance + events + hardening + sessions"},
{id:85,d:5,q:"What is the Daily Compliance Score in the Security Center?",opts:["A count of failed login attempts in the last 24 hours", "The percentage of incidents resolved within SLA targets in the past day", "A percentage score indicating how compliant the instance's security property settings are with recommended hardening guidelines", "A daily export of the instance's ACL configuration"],ans:[2],multi:false,src:"course",exp:"Daily Compliance Score = % of hardening properties correctly set"},
{id:86,d:5,q:"What does the Shared Responsibility Model mean in the context of ServiceNow cloud security?",opts:["ServiceNow and the customer split all security responsibilities 50/50", "ServiceNow is responsible for securing the cloud platform infrastructure; the customer is responsible for configuring and securing their instance (data, access controls, integrations, customizations)", "The customer is fully responsible for all security, including the underlying cloud hardware", "ServiceNow handles all instance security automatically with no customer action required"],ans:[1],multi:false,src:"course",exp:"ServiceNow secures platform; customer secures instance"},
{id:87,d:6,q:"An admin makes several changes on a development instance while an update set is the current set. Which of these are captured in that update set?",opts:["A new business rule on the Incident table", "Incident records created by users while testing", "A catalog item definition and its variables", "Catalog orders submitted during testing"],ans:[0, 2],multi:true,src:"docs",exp:"customizations-tracked-update-sets.md: update sets \"capture configuration details but exclude task or process data — they record catalog item definitions, variables, and variable choices, but not submitted orders or catalog tasks\""},
{id:88,d:6,q:"Before moving an update set between instances, an admin compares two local update sets. Which two statements describe what the comparison produces and what must be done with it?",opts:["It generates a collision report, where duplicate collision numbers show the same change in separate update sets", "It merges the conflicting records automatically", "Collisions are resolved by deleting the unwanted update record from one of the sets", "It rolls back whichever update set is older", "It exports both update sets to CSV for review"],ans:[0, 2],multi:true,src:"docs",exp:"t_CompareLocalUpdateSets.md: comparison generates a collision report; resolve by deleting the unwanted update record. Nothing merges or rolls back automatically"},
{id:89,d:6,q:"How does the documentation define an update set?",opts:["An XML file containing record details that identify the set, a list of configuration changes, and a state governing whether another instance can retrieve and apply them", "A database backup of a single application scope", "A scheduled job that copies data between instances", "A point-in-time snapshot of the CMDB"],ans:[0],multi:false,src:"docs",exp:"exploring-system-update-sets.md: an update set is an XML file containing record details that identify it, a list of configuration changes, and a state"},
{id:90,d:6,q:"An update set has been retrieved on a test instance. Which actions let the admin inspect exactly what will be committed?",opts:["Select Show All Preview Records on the update set record", "Export the update set to CSV", "Review the Update Set Preview Problems related list", "Run a discovery schedule against the target instance"],ans:[0, 2],multi:true,src:"docs",exp:"t_PreviewARemoteUpdateSet.md: Show All Preview Records and the Update Set Preview Problems related list are the documented inspection points"},
{id:91,d:6,q:"Instance Scan checks are focused rules that detect anomalies or opportunities in an instance. Which categories of vulnerability does the documentation say checks are defined to identify?",opts:["Security and performance", "License consumption tiers", "Upgrade best practices, manageability and user experience", "SLA breach counts", "User login frequency"],ans:[0, 2],multi:true,src:"docs",exp:"hs-intro-health-check.md: checks \"identify security, upgrade best practices, manageability, user experience and performance vulnerabilities\""},
{id:92,d:6,q:"What does the State field on an update set determine?",opts:["Whether another instance can retrieve and apply its configuration changes", "Which MID Server processes it", "How long its XML payload is retained", "Which domain its records belong to"],ans:[0],multi:false,src:"docs",exp:"exploring-system-update-sets.md: the state \"determines whether another instance can retrieve and apply configuration changes\""},
{id:93,d:6,q:"An admin merges three update sets into one. Which two statements are true of the merge?",opts:["Only update sets belonging to the same application can be merged", "The most recent change for each object is moved into the new set", "Every change from all three sets is copied into the new set", "The original update sets are deleted automatically"],ans:[0, 1],multi:true,src:"docs",exp:"t_MergeUpdateSets.md: same application only; \"the most recent change for each object is moved\". Originals must be deleted manually to avoid committing an older change"},
{id:94,d:6,q:"A collision report shows the same change in two update sets. The admin opens the unwanted update record and deletes it. What has that actually done?",opts:["Undone the customization on the instance", "Removed the record of the customization, without undoing the customization", "Backed out the whole update set", "Set the update set to Ignore"],ans:[1],multi:false,src:"docs",exp:"t_CompareLocalUpdateSets.md: \"Deleting the update record only removes the record of the customization, it doesn't undo the customization\" — the trap in this topic"},
{id:95,d:6,q:"Which action does the documentation explicitly warn can damage the configuration of the instance?",opts:["Backing out the Default update set", "Saving an update set as a local XML file", "Marking an update set Complete", "Previewing a retrieved update set"],ans:[0],multi:false,src:"docs",exp:"t_BackOutUpdateSet.md: \"Don't back out the Default update set. This action can damage the configuration of the instance\""},
{id:96,d:6,q:"An admin must move an update set to an instance that cannot reach the source instance over the network. Which documented option produces a file they can carry across?",opts:["Save the update set as a local XML file", "Export the update set to CSV", "Export the update set to JSON", "Schedule an instance clone"],ans:[0],multi:false,src:"docs",exp:"t_SaveAnUpdateSetAsAnXMLFile.md: update sets are XML; the local XML file is the documented offline transport. Retrieve is the instance-to-instance route"},
{id:97,d:6,q:"What is the documented order for promoting a completed update set from development to test?",opts:["Mark Complete on dev → Retrieve on test → Preview on test → Commit on test", "Commit on dev → Retrieve on test → Mark Complete on test → Preview on test", "Retrieve on dev → Preview on dev → Commit on dev → Mark Complete on test", "Mark Complete on dev → Commit on test → Preview on test → Retrieve on test"],ans:[0],multi:false,src:"docs",exp:"exploring-system-update-sets.md workflow + t_PreviewARemoteUpdateSet.md: complete on dev, retrieve on test, preview, then commit. Preview sits between retrieve and commit"},
{id:98,d:6,q:"A team needs to move a newly built catalog item, its variables and its business rules from development to production — but not the test orders staff submitted while building it. Which mechanism is designed for this?",opts:["An update set", "An import set", "An instance clone", "A scheduled data export"],ans:[0],multi:false,src:"docs",exp:"Update sets carry configuration, not data (customizations-tracked-update-sets.md). For data between instances the docs point to an instance-to-instance import"},
{id:99,d:6,q:"Why does the platform block adding the update_synch attribute to a dictionary record where it isn't predefined?",opts:["On core tables representing information across several tables it creates duplicate update records, causing conflicts that are difficult to troubleshoot and repair", "It disables the update set picker for every user on the instance", "It converts the table into a data-only table", "It prevents the table from being included in an instance clone"],ans:[0],multi:false,src:"docs",exp:"customizations-tracked-update-sets.md: on core tables the attribute \"creates duplicate update records, causing major conflicts that are difficult to troubleshoot and repair\""},
{id:100,d:6,q:"On a production instance, why would an admin set committed update sets to the Ignore state?",opts:["To help prevent additional commits when the instance is cloned", "To roll back the changes they contain", "To delete them from the history of changes", "To compress their XML for storage"],ans:[0],multi:false,src:"docs",exp:"create-select-update-set.md: \"Set completed update sets on the production instance to ignore to help prevent additional commits when cloning the instance.\" Ignore also stops transfer to another instance"},
{id:101,d:6,q:"What is the scripting language used in ServiceNow?",opts:["Java", "AngularJS", "JavaScript", "Jelly"],ans:[2],multi:false,src:"course",exp:"JavaScript is the scripting language (official blueprint sample Q5)"},
{id:102,d:6,q:"What is a Business Rule in ServiceNow?",opts:["A server-side script that runs when a record is displayed, inserted, updated, deleted, or when a table is queried", "A client-side script that validates fields before form submission", "A scheduled job that runs on a defined interval", "A configuration record that defines escalation paths"],ans:[0],multi:false,src:"course",exp:"Business Rule = server-side script on record events"},
{id:103,d:6,q:"A Business Rule is configured with \"When = before\" and \"Insert = true\". When exactly does it execute?",opts:["Before the form is displayed to the user", "After the user submits the form and after the record is saved", "After the user submits the form but before the record is saved to the database", "Only when triggered manually by a script"],ans:[2],multi:false,src:"course",exp:"Before = after form submit, BEFORE database write"},
{id:104,d:6,q:"Which of the following are valid \"When\" settings for a Business Rule?",opts:["Before", "Inline", "After", "On Submit"],ans:[0, 2],multi:true,src:"course",exp:"Valid: Before, After, Async, Display"},
{id:105,d:6,q:"What are the predefined global variables available in a Business Rule?",opts:["current — represents the current state of the record being acted on", "g_form — the client-side form object", "previous — the state of the record before the current transaction (update/delete only)", "window — the browser window object"],ans:[0, 2],multi:true,src:"course",exp:"current + previous are the two key BR variables"},
{id:106,d:6,q:"What is a UI Policy in ServiceNow?",opts:["A server-side rule that enforces mandatory fields at the database level", "A no-code browser-side configuration that dynamically controls form field behavior (mandatory, read-only, hidden) based on conditions", "A policy that defines which users can access a specific module", "A visual theme setting applied to the Service Portal"],ans:[1],multi:false,src:"course",exp:"UI Policy = no-code, browser-side field control"},
{id:107,d:6,q:"What is the key difference between a UI Policy and a Data Policy?",opts:["UI Policies apply only in the browser (forms); Data Policies enforce field rules at the database level and apply regardless of access method (forms, imports, APIs)", "UI Policies are server-side; Data Policies are client-side", "UI Policies apply to all tables; Data Policies apply only to custom tables", "UI Policies set field visibility; Data Policies set record-level security"],ans:[0],multi:false,src:"course",exp:"UI Policy = browser only; Data Policy = database-level"},
{id:108,d:6,q:"What is a Script Include in ServiceNow?",opts:["A tag that embeds an external JavaScript file into a form page", "A client-side script that runs on every page load", "A reusable server-side JavaScript library callable from business rules, other scripts, and client scripts via GlideAjax", "A scheduled script that executes daily"],ans:[2],multi:false,src:"course",exp:"Script Include = reusable server-side JS library"},
{id:109,d:1,q:"A ServiceNow administrator searches \"password reset\" using the global search bar in the top banner. Which of the following best describes what is searched?",opts:["Only the currently displayed list in the active module", "Only the Knowledge Base table", "Multiple configured source tables simultaneously — such as Knowledge, Catalog, and Incidents — based on defined search sources", "The Application Navigator filter only"],ans:[2],multi:false,src:"course",exp:"Global search = multi-table simultaneous search across configured search sources"},
{id:110,d:1,q:"A ServiceNow user wants to quickly navigate to a module without using the mouse. Which keyboard shortcut focuses the Application Navigator filter text box?",opts:["Ctrl+F", "Ctrl+N", "The period key (.)", "Alt+Tab"],ans:[2],multi:false,src:"course",exp:"Period key (.) focuses the Application Navigator filter input"},
{id:111,d:1,q:"An admin wants to verify the exact form views and permissions a standard user sees, without logging out of their own admin session. Which ServiceNow feature enables this?",opts:["Create a duplicate user account with the same roles and test manually", "System Logs > User Activity viewer", "Impersonate User — accessible from the profile/avatar menu — temporarily switches the admin's session to act as the selected user", "Simulate Mode in the Security Center"],ans:[2],multi:false,src:"course",exp:"Impersonate User = admin tests another user's view without a separate login"},
{id:112,d:5,q:"An HR team stores Social Security Numbers in a custom field. They need the stored values to be unreadable even with direct database access. Which ServiceNow feature provides this?",opts:["ACL rules set to deny read for all roles", "Setting the field type to String and hiding it with a UI Policy", "ServiceNow Vault field-level encryption, which encrypts the field's stored value at rest", "Data Policy configured as read-only"],ans:[2],multi:false,src:"course",exp:"ServiceNow Vault field-level encryption = at-rest protection; encrypted fields can't be filtered or reported on"},
{id:113,d:5,q:"Which of the following accurately describes ServiceNow's default vs. optional security measures?",opts:["Field-level encryption is on by default; TLS requires purchasing an SSL certificate", "TLS encryption for all data in transit is provided by default; field-level encryption (data at rest) requires explicit configuration via ServiceNow Vault", "Both TLS and field-level encryption are enabled by default for all tables", "Neither is enabled by default; both require separate plugin activations"],ans:[1],multi:false,src:"course",exp:"TLS in transit = default; field-level encryption (at rest) = explicit config via Vault"},
{id:114,d:5,q:"A company's security policy requires all ServiceNow users to complete a second authentication factor at login. How is Multi-Factor Authentication (MFA) enforced?",opts:["Setting password complexity to 16+ characters in System Security", "Configuring MFA via SAML/SSO integration with an external Identity Provider (such as Okta or Azure AD), or via ServiceNow's built-in MFA settings", "Creating an Inbound Action that sends a verification email each session", "Writing a Business Rule that prompts users on every login event"],ans:[1],multi:false,src:"course",exp:"MFA via SAML/SSO IdP or built-in MFA settings; not achievable via business rules alone"},
{id:115,d:5,q:"A compliance officer needs a full audit trail showing who changed the Priority field on any Incident, including before/after values and timestamps. What must be configured?",opts:["Write a Business Rule that logs changes to a custom table on every update", "Enable the Audit attribute (set to true) on the Priority field's dictionary entry for the Incident table — changes are tracked in the sys_audit table", "Activate the CMDB reconciliation plugin", "Configure a Data Policy with read-only enforcement on the Priority field"],ans:[1],multi:false,src:"course",exp:"Audit attribute on dictionary entry = field-level change tracking in sys_audit"},
{id:116,d:5,q:"A security team wants to query all changes made to the Priority field on Incident records in the last 30 days. Which table holds this data?",opts:["sys_log", "sys_history_line", "sys_audit", "syslog_transaction"],ans:[2],multi:false,src:"course",exp:"sys_audit = field change history when Audit=true on dictionary entry"},
{id:117,d:5,q:"Where in ServiceNow are password complexity rules (minimum length, required character types, expiration) configured, and which role can modify them?",opts:["System Properties > UI Settings — any admin can modify", "User Administration > User Preferences — user_admin role required", "System Security > Password Policy — requires the security_admin (elevated) role", "ACL rules on the sys_user table — requires the admin role"],ans:[2],multi:false,src:"course",exp:"Password Policy under System Security; requires elevated security_admin role"},
{id:118,d:5,q:"A developer must store an API key in a ServiceNow field that must never appear in plain text on forms or in list views. Which field type achieves this?",opts:["String (plain text, no masking)", "Password2 — stores the value securely and always displays it as asterisks () in the UI", "Reference field pointing to a separate secure credentials table", "HTML field with CSS display:none applied in a UI Script"],ans:[1],multi:false,src:"course",exp:"Password2 field type = masked display (), value stored securely"},
{id:119,d:5,q:"A user with the itil role reports they cannot open one specific Incident, even though all other Incidents are accessible. Which tool best helps an admin identify which ACL rule is blocking access?",opts:["Dictionary editor — review field-level attributes", "ACL Debugger (available with the security_admin elevated role), which evaluates all applicable ACL rules for the specific user and record combination", "Import Set transform log", "Virtual Agent conversation analyzer"],ans:[1],multi:false,src:"course",exp:"ACL Debugger with security_admin role = evaluates rules per user/record combination"},
{id:120,d:5,q:"An external application will call the ServiceNow REST API to create Incidents automatically. Which authentication method is recommended over Basic Auth?",opts:["API keys passed as URL query parameters", "Hard-coded credentials embedded in the HTTP request header", "OAuth 2.0 — token-based authentication where credentials are exchanged for a time-limited access token, reducing credential exposure", "IP allowlist only, with no authentication credentials required"],ans:[2],multi:false,src:"course",exp:"OAuth 2.0 = token-based, time-limited; preferred over Basic Auth"},
{id:121,d:5,q:"A user holds the itil role through membership in the \"ITSM Team\" group. When an admin removes the user from the group, when does the loss of the itil role take effect?",opts:["At midnight during the next scheduled synchronization", "Only after the user logs out and back in", "After the MID Server is restarted", "Immediately when the group membership removal is saved"],ans:[3],multi:false,src:"course",exp:"Role inherited via group = removed immediately when membership save is committed"},
{id:122,d:6,q:"Which of the following are the four Client Script execution types in ServiceNow?",opts:["onLoad — fires when the form loads in the browser", "onChange — fires when a watched field value changes", "onSubmit — fires when the user submits the form", "onCellEdit — fires when a cell is edited inline in a list view"],ans:[0, 1, 2, 3],multi:true,src:"course",exp:"All four are valid Client Script types: onLoad, onChange, onSubmit, onCellEdit"},
{id:123,d:6,q:"A developer needs two behaviors: (1) pre-populate the Assignment Group whenever a new Incident form opens, and (2) clear the Assigned To field whenever the Category field changes. Which Client Script types handle each requirement?",opts:["(1) onSubmit; (2) onLoad", "(1) onLoad — fires when the form opens; (2) onChange on the Category field — fires when its value changes", "(1) onChange on the Assignment Group field; (2) onSubmit on the Category field", "Both should use Business Rules with \"When = display\""],ans:[1],multi:false,src:"course",exp:"onLoad = form-open pre-population; onChange = reactive field clearing on change"},
{id:124,d:6,q:"A developer needs to query all active Incidents assigned to the currently logged-in user in a server-side script. Which code pattern is correct?",opts:["var gr = new GlideRecord('incident'); gr.get('active=true'); gr.query();", "var gr = new GlideRecord('incident'); gr.addQuery('active', true); gr.addQuery('assigned_to', gs.getUserID()); gr.query(); while (gr.next()) { /* process */ }", "var gr = GlideRecord.select('incident').where('active', true);", "var gr = new GlideQuery('incident').where('active', true).toGlideRecord();"],ans:[1],multi:false,src:"course",exp:"GlideRecord: addQuery() × 2, then query(), then while(gr.next()) is the correct pattern"},
{id:125,d:6,q:"A developer wants to call an external REST API from a Business Rule, storing the endpoint URL and credentials outside the script for reuse and easy management. Which ServiceNow record type is used?",opts:["Transform Map record", "MID Server record", "REST Message record (sys_rest_message) — found under System Web Services > Outbound > REST Message", "Inbound Action record"],ans:[2],multi:false,src:"course",exp:"REST Message (sys_rest_message) = reusable outbound REST endpoint + auth profile"},
{id:126,d:6,q:"In a server-side script using the RESTMessageV2 API, which method sends the outbound HTTP request, and what type does it return?",opts:[".send() — returns a raw String of the response body", ".execute() — returns a RESTResponseV2 object; call .getBody() on it to retrieve the response body string", ".run() — returns a Boolean indicating success or failure", ".dispatch() — automatically parses the response as a JSON object"],ans:[1],multi:false,src:"course",exp:".execute() sends the request; returns RESTResponseV2; .getBody() reads the response"},
{id:127,d:6,q:"An admin needs a server-side script to run automatically every night at 2:00 AM to archive old records. Which ServiceNow feature handles this, and which table stores these definitions?",opts:["Business Rule with \"When = async\" — stored in sys_script", "Flow Designer scheduled trigger — stored in sys_flow", "Scheduled Script Execution — found under System Definition > Scheduled Jobs, stored in the sys_trigger table", "MID Server probe — stored in ecc_queue"],ans:[2],multi:false,src:"course",exp:"Scheduled Script Execution = time-based server-side scripts; stored in sys_trigger"},
{id:128,d:6,q:"A developer debugging a Business Rule uses both gs.log() and gs.info(). What is the key difference, and where do both messages appear?",opts:["gs.log() sends output to an external syslog server; gs.info() writes to the database", "gs.log() is client-side only; gs.info() is server-side only", "Both write to the system log (viewable at System Logs > System Log > All, stored in the syslog table); gs.log() writes at the default log level while gs.info() writes at INFO level — affecting log filtering and verbosity settings", "gs.log() creates an Incident record; gs.info() writes to the Knowledge Base"],ans:[2],multi:false,src:"course",exp:"Both write to syslog table; gs.info() = INFO level; gs.log() = default level"},
{id:129,d:1,q:"A user right-clicks on a record row in a ServiceNow list. What appears?",opts:["A drag-and-drop handle to reorder the record", "The context menu, offering options such as Open, Open in New Tab, Assign Tag, Copy sys_id, and Show Live Feed", "A field-level dictionary popup for the row's primary field", "The Update Set history for that record"],ans:[1],multi:false,src:"course",exp:"Right-click on a list row = context menu (Open, Open in New Tab, Assign Tag, Copy sys_id, etc.)"},
{id:130,d:2,q:"An administrator needs to confirm which ServiceNow release (e.g., Xanadu, Yokohama) and patch level is currently running on their instance. Where should they look?",opts:["System Logs > All", "The Update Set history list", "Navigate to stats.do in the browser URL, or go to System > System Diagnostics > Stats — this page shows the current build, release name, and patch level", "Check the Plugin Manager for the currently active plugins"],ans:[2],multi:false,src:"course",exp:"stats.do or System > System Diagnostics > Stats = shows release name + build + patch level"},
{id:131,d:3,q:"Which of the following are valid UI Action types in ServiceNow?",opts:["Form button — a clickable button rendered on a record form's header bar", "List choice — an option in the \"Actions on selected rows\" dropdown in a list view", "Form link — a link that appears in the Related Links section at the bottom of a form", "Data Policy — enforces field attribute rules at the database level"],ans:[0, 1, 2],multi:true,src:"course",exp:"Form button, List choice, Form link are UI Action types; Data Policy is a separate feature"},
{id:132,d:3,q:"A UI Action has its \"Client\" checkbox enabled. What does this mean?",opts:["The script executes on the server before the record is written to the database", "The action is restricted to users with the client_admin role", "The script runs in the user's browser as client-side JavaScript and can use g_form, g_user, and other client-side APIs to manipulate the form without a server round-trip", "The action triggers a MID Server probe on the local network"],ans:[2],multi:false,src:"course",exp:"Client checkbox = browser-side JS; can use g_form/g_user APIs without server round-trip"},
{id:133,d:3,q:"How does a user apply a tag to a record in ServiceNow?",opts:["Edit the sys_dictionary entry for the table and add a tag field", "Right-click the record row in a list (context menu > Assign Tag) or use the tag icon on the form header, then select an existing tag or create a new one", "Add a Business Rule with a current.addTag() server-side call", "Modify the record's Update Set entry and add a tag metadata block"],ans:[1],multi:false,src:"course",exp:"Set tag via right-click context menu (Assign Tag) or the tag icon on the form header"},
{id:134,d:3,q:"By default, a tag that a user creates and applies to records in ServiceNow is:",opts:["Public — immediately visible to all users on the instance", "Visible only to users with the tag_admin role", "Personal — visible only to the creator; the user can optionally change its visibility to share it with others", "Automatically published to the Service Portal as a knowledge category"],ans:[2],multi:false,src:"course",exp:"Tags are personal (creator-only) by default; visibility can be changed to share"},
{id:135,d:5,q:"A customer asks: \"Are data values stored in ServiceNow fields encrypted at rest by default?\" What is the correct answer?",opts:["Yes — all field values are encrypted at rest by default using AES-256 with no configuration required", "Yes — but only for fields on tables that extend the task table", "No — field-level encryption at rest is not enabled by default; it requires explicit configuration using ServiceNow Vault (Column Level Encryption) on a per-field basis", "No — encryption at rest is not available in ServiceNow at all; only TLS in transit is supported"],ans:[2],multi:false,src:"course",exp:"Field-level encryption NOT on by default; requires ServiceNow Vault (CLE) config per field"},
{id:136,d:5,q:"By default, which role does a base-system administrator NOT hold at login, and must manually elevate to obtain?",opts:["security_admin", "user_admin", "itil_admin", "catalog_admin"],ans:[0],multi:false,src:"docs",exp:"security-admin-role.md: \"In the base system, only the default System Administrator (admin) user has the security_admin role. Since it requires elevating privileges, the admin user does not have this role at login.\""},
{id:137,d:5,q:"How long does an elevated privilege role last once a user elevates to it?",opts:["For the duration of that user session only — session timeout or logout removes it", "Permanently, until an admin revokes it", "For 24 hours", "Until the next instance clone"],ans:[0],multi:false,src:"docs",exp:"c_ElevatedPrivilege.md: \"An elevated privilege role lasts only for the duration of your user session. Session timeout or logout removes the role.\""},
{id:138,d:5,q:"A user holds only the user_admin role. Which statement is true about what they can grant?",opts:["They cannot grant the admin role — the granting user must also have the admin role", "They can grant any role including admin", "They can grant admin but not itil", "They can grant admin only after elevating"],ans:[0],multi:false,src:"docs",exp:"c_ElevatedPrivilege.md: \"To grant the admin role to a user, the granting user must also have the admin role... a user with only the user_admin role cannot grant the admin role to other users.\""},
{id:139,d:5,q:"An admin wants to give a colleague the security_admin role. What must the granting admin do first?",opts:["Elevate to security_admin themselves — a user with only the admin role cannot grant it", "Nothing extra; the admin role alone is sufficient", "Activate the High Security plugin", "Add the colleague to a group that already contains admin"],ans:[0],multi:false,src:"docs",exp:"c_ElevatedPrivilege.md: the granting user \"must also have the admin role and must elevate to the security_admin role before granting\" it. \"A user with only the admin role cannot grant the security_admin role to other users.\""},
{id:140,d:5,q:"Elevated role A contains elevated role B. A user elevates to role A. What privileges do they have?",opts:["Only role A's — they must elevate to role B separately to get its privileges", "Both A and B, because A contains B", "Neither, until an admin approves", "Both, but only until the page is refreshed"],ans:[0],multi:false,src:"docs",exp:"c_ElevatedPrivilege.md: \"if elevated role A contains elevated role B, even if you elevate to role A, you must still elevate to role B to get its privileges.\""},
{id:141,d:5,q:"Which two capabilities does the security_admin role provide?",opts:["Creating and changing access controls", "Changing High Security Settings", "Creating update sets", "Running instance clones", "Publishing knowledge articles"],ans:[0, 1],multi:true,src:"docs",exp:"security-admin-role.md: security_admin \"lets users create and change access controls and change High Security Settings.\""},
{id:142,d:5,q:"Additional users have been granted the admin role on an instance. Which statement is true about role elevation?",opts:["Only the base system admin can elevate to a privileged role", "Every admin can elevate to any privileged role", "Elevation is available to any user with a role", "Elevation requires the user_admin role"],ans:[0],multi:false,src:"docs",exp:"t_ElevateToAPrivilegedRole.md: \"If you grant additional users the admin role, they cannot elevate to a privileged role. Only the base system admin can elevate.\""},
{id:143,d:5,q:"Which of these does domain separation segregate within a single instance?",opts:["Application data", "Business logic such as notifications, business rules and UI policies", "The instance's release version", "The database vendor", "Update set numbering"],ans:[0, 1],multi:true,src:"docs",exp:"bp-dom-sep-definition.md: domain separation segregates \"application data, UI, and business logic\"; business logic separation covers \"email notifications, business rules, client scripts, UI policy, and UI actions.\""},
{id:144,d:5,q:"What does hierarchical modeling in domain separation allow?",opts:["Parent tenants can access child tenant resources, and parent business logic runs for children", "Each domain must be completely isolated with no relationships", "Domains can only be one level deep", "Child domains automatically inherit all admin users"],ans:[0],multi:false,src:"docs",exp:"bp-dom-sep-definition.md: hierarchical modeling \"supports nested-multitenancy so parent tenants can access child customer resources. The business logic for parent customers runs automatically for child customers.\""},
{id:145,d:5,q:"A non-admin user attempts to add someone to a group that contains the admin role. What happens?",opts:["It is blocked — non-admin users cannot add a user to a group that contains the admin role", "It succeeds, since group membership is not role-controlled", "It succeeds but the role is not applied", "It requires security_admin elevation only"],ans:[0],multi:false,src:"docs",exp:"c_ElevatedPrivilege.md: \"Non-admin users cannot add a user to a group that contains the admin role.\""},
{id:146,d:5,q:"What is the role of an import set table in a data import?",opts:["A staging area holding records from a data source before they are transformed", "The final production table the data lands in", "A backup of the target table taken before import", "A log of failed transform attempts"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetsKeyConcepts.md: \"The import sets table acts as a staging area for records imported from a data source.\""},
{id:147,d:5,q:"An import needs to populate an encrypted field on the target table. What does the documentation say about this?",opts:["It cannot be done — import sets run as user System and cannot add data to encrypted fields", "It works if the transform map has a coalesce field", "It works only for JDBC data sources", "It works if the importing user holds security_admin"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetsKeyConcepts.md: \"Import sets run as user System and therefore cannot add data to encrypted fields.\" A favourite trap — the permission is not the issue."},
{id:148,d:5,q:"A column is missing from an import set table. What is the documented way to add it?",opts:["Add the column to the input data, then run Test Load 20 Records or Load All Records to generate it", "Add the column manually in the dictionary", "Add it to the target table and it will propagate back", "Recreate the data source from scratch"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetsKeyConcepts.md: \"first add the column to the input data, then select Test Load 20 Records or Load All Records to auto generate the columns.\""},
{id:149,d:5,q:"Why does the documentation warn against manually adding columns to an import set table?",opts:["It can break the table's scheduled cleanup and leave orphaned records", "It permanently locks the data source", "It converts the table to a data-only table", "It removes the table from update set tracking"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetsKeyConcepts.md: manually adding columns \"can negatively impact the table's scheduled cleanup and may lead to an incomplete cleanup and orphaned records.\""},
{id:150,d:5,q:"Which of these are documented data source types?",opts:["LDAP", "JDBC", "Update Set", "CMDB Baseline", "Attachment Registry"],ans:[0, 1],multi:true,src:"docs",exp:"c_DataSources.md lists File, JDBC, LDAP, OIDC, REST (Integration Hub), Data Stream and Custom (Load by Script). Update Set is a deployment mechanism, not a data source."},
{id:151,d:5,q:"A transform map has no coalesce field defined. What happens on transform?",opts:["Every imported row is treated as a new record; no existing records are updated", "Every imported row updates the first matching target record", "The transform fails validation", "Rows are skipped until a coalesce field is set"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetCoalesce.md: \"If no coalesce is defined, all imported rows are treated as new records. No existing records are updated.\""},
{id:152,d:5,q:"A transform map coalesces on a single field. An import row's coalesce value matches an existing target record. What happens?",opts:["The existing target record is updated with the import row's values", "A duplicate record is created", "The import row is skipped", "The target record is deleted and recreated"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetCoalesce.md: \"If an existing record with a matching value in the target table is found, that record is updated. If no matching record is found, then a new record is created.\""},
{id:153,d:5,q:"A transform map coalesces on three fields. Two of the three match an existing target record. What happens?",opts:["A new record is created — all coalesce field values must match to coalesce on multiple fields", "The existing record is updated because a majority matched", "The transform throws an error", "The record is written to the reject table"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetCoalesce.md: \"All coalesce field values between the target and staging tables must match to coalesce with multiple fields.\""},
{id:154,d:5,q:"Why does the documentation say to coalesce only on fields that hold unique values?",opts:["If more than one target record matches, only the first matching record is updated", "Non-unique fields cannot be selected as coalesce fields", "Coalescing on a non-unique field deletes duplicates", "The transform map will not save otherwise"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetCoalesce.md: \"If more than one record in the target table matches the specified coalesce options, only the first matching record in the target table is updated.\""},
{id:155,d:5,q:"A team wants a transform to update matching records but skip rows with no match. Which documented approach achieves this?",opts:["Specify a coalesce field and add an onBefore script setting ignore = true when action == 'insert'", "Remove the coalesce field entirely", "Set the data source to Updates Only", "Delete the import set table before each run"],ans:[0],multi:false,src:"docs",exp:"c_ImportSetCoalesce.md, Updates only: specify a coalesce field and add if (action == 'insert') ignore = true; as an onBefore script."},
{id:156,d:3,q:"In a list filtered to active, priority 1 incidents, a user clicks New. What does the documentation say happens?",opts:["The new record opens preset with Active selected and Priority set to 1 - Critical", "The new record opens empty, ignoring the filter", "The filter is cleared and the list reloads", "The user is prompted to choose whether to apply the filter"],ans:[0],multi:false,src:"docs",exp:"c_UsingFiltersAndBreadcrumbs.md: \"In a list filtered for active, priority 1 incidents, clicking New opens a record preset with Active selected and Priority set to 1 - Critical.\""},
{id:157,d:3,q:"An admin does not want a particular field pre-populated when a user clicks New from a filtered list. Which dictionary attribute achieves that?",opts:["ignore_filter_on_new=true", "no_preset=true", "skip_filter=true", "readonly_on_new=true"],ans:[0],multi:false,src:"docs",exp:"c_UsingFiltersAndBreadcrumbs.md: add the dictionary attribute ignore_filter_on_new=true to the field you don't want populated."},
{id:158,d:3,q:"Which role, besides admin, allows a user to configure form layout and form design?",opts:["personalize_form", "form_admin", "ui_admin", "itil_admin"],ans:[0],multi:false,src:"docs",exp:"c_FormDesign.md / configure-form-layout.md: \"Administrators or users with the personalize_form role can use the form design feature.\""},
{id:159,d:3,q:"Starting with the Australia release, which tool does the documentation direct you to instead of Form Designer?",opts:["Form Builder", "UI Builder", "Service Portal Designer", "App Engine Studio"],ans:[0],multi:false,src:"docs",exp:"c_FormDesign.md: \"Starting with the Australia release, form designer is being prepared for future deprecation. Try configuring your forms with Form Builder instead.\""},
{id:160,d:3,q:"In the form designer's field navigator, what happens when you add an item from the Field Types tab and save?",opts:["New fields are created in the selected table", "Only the form layout changes; no fields are created", "The field is added to every view of that table", "A dictionary override is created"],ans:[0],multi:false,src:"docs",exp:"c_FormDesign.md: \"Adding a field type to the form layout creates fields in the selected table when the form layout is saved.\" Fields tab adds existing fields; Field Types creates new ones."},
{id:161,d:3,q:"How many forms can exist for a given table and view combination?",opts:["Exactly one — each form is tied to a unique table and view combination", "One per role", "Unlimited", "One per application scope"],ans:[0],multi:false,src:"docs",exp:"c_FormDesign.md: \"Each form is tied to a unique table and view combination... there can only be one form for the incident table default view.\""},
{id:162,d:3,q:"In Configure > Form Layout, what do available items shown in green with a plus sign represent?",opts:["Related tables whose fields are reached by dot-walking", "Mandatory fields", "Fields created since the last update set", "Fields inherited from the parent table"],ans:[0],multi:false,src:"docs",exp:"configure-form-layout.md: \"Available items that appear in green followed by a plus (+) sign represent related tables. To access fields on these tables, use dot-walking.\""},
{id:163,d:3,q:"Why does the documentation warn against adding the same editable field to more than one section of a form?",opts:["It can cause data loss and prevent UI and data policies working properly", "It doubles the form load time", "It breaks the update set that contains the form", "It is blocked by the platform automatically"],ans:[0],multi:false,src:"docs",exp:"configure-form-layout.md warning: two or more instances of an editable field \"can cause data loss and prevent the proper functioning of UI and data policies.\""},
{id:164,d:3,q:"What are the three parts of a condition in the condition builder?",opts:["Field, Operator, Value", "Table, Field, Script", "Field, Value, Role", "Operator, Value, Order"],ans:[0],multi:false,src:"docs",exp:"c_ConditionBuilder.md: \"A condition consists of three parts: Field, Operator, Value.\""},
{id:165,d:3,q:"In the condition builder, what determines which operators are offered?",opts:["The field type — for example, greater than applies to Priority but not to Active", "The user's role", "The table's application scope", "The number of records in the table"],ans:[0],multi:false,src:"docs",exp:"c_ConditionBuilder.md: the operator list is \"based on the field type. For example... the greater than operator does not apply to the Active field but it does apply to the Priority field.\""},
{id:166,d:3,q:"In a list breadcrumb, what happens when a user clicks a condition partway along?",opts:["All conditions to its right are removed", "All conditions to its left are removed", "Only that condition is removed", "The whole filter is cleared"],ans:[0],multi:false,src:"docs",exp:"c_UsingFiltersAndBreadcrumbs.md: \"Clicking a breadcrumb removes all the conditions to its right.\""},
{id:167,d:3,q:"In a list breadcrumb, what does clicking the condition separator (>) before a condition do?",opts:["Removes only that condition", "Removes all conditions to its right", "Removes all conditions", "Inverts that condition"],ans:[0],multi:false,src:"docs",exp:"c_UsingFiltersAndBreadcrumbs.md: \"Clicking the condition separator (>) before a condition removes only that condition.\" The pair with Q166 is the trap."},
{id:168,d:3,q:"How are breadcrumb conditions ordered?",opts:["Left to right, most general on the left and most specific on the right", "Left to right, most specific on the left", "In the order the fields appear on the form", "Alphabetically by field name"],ans:[0],multi:false,src:"docs",exp:"c_UsingFiltersAndBreadcrumbs.md: \"ordered from left to right. The left condition is the most general, and the right condition is the most specific.\""},
{id:169,d:3,q:"By default, which users cannot see list breadcrumbs and filters?",opts:["Users with no roles", "Users with the itil role", "Users outside the Default domain", "Users on the Service Portal only"],ans:[0],multi:false,src:"docs",exp:"c_UsingFiltersAndBreadcrumbs.md: \"By default, a user with no roles cannot see the breadcrumbs or filter.\""},
{id:170,d:3,q:"What does the list editor let a user do?",opts:["Edit field values directly in a list without opening a form", "Edit the list layout for all users", "Bulk delete records from a list", "Export the list to Excel"],ans:[0],multi:false,src:"docs",exp:"r_MethodsForListEdits.md: \"The list editor lets you edit field values in a list without opening a form.\""},
{id:171,d:3,q:"Which two statements about the list editor are true?",opts:["List editing is disabled by default for some tables", "Fields of certain types cannot be edited from lists", "It requires the personalize_form role", "It bypasses business rules on the table", "It is available only in the Service Portal"],ans:[0, 1],multi:true,src:"docs",exp:"r_MethodsForListEdits.md: \"By default, list editing is disabled for some tables. Fields of certain types cannot be edited from lists.\""},
{id:172,d:5,q:"What does a many-to-many table relationship create between two tables?",opts:["A bi-directional relationship so related records are visible from both tables in a related list", "A one-way reference from parent to child", "A database view joining the two tables", "An extension of one table from the other"],ans:[0],multi:false,src:"docs",exp:"t_CreateAManyToManyRelationship.md: \"Create a bi-directional relationship between two tables, so that the related records are visible from both tables in a related list.\""},
{id:173,d:5,q:"Which table stores custom many-to-many definitions?",opts:["sys_m2m", "sys_relationship", "sys_dictionary", "sys_db_object"],ans:[0],multi:false,src:"docs",exp:"t_CreateAManyToManyRelationship.md: \"The Many to Many Definitions [sys_m2m] table allows administrators to create custom many-to-many relationships.\""},
{id:174,d:5,q:"How do many-to-many tables count against an instance's custom table allotment?",opts:["They aren't considered custom tables and don't count toward the allotment", "Each counts as one custom table", "Each counts as two custom tables", "They count only when they extend Task"],ans:[0],multi:false,src:"docs",exp:"t_CreateAManyToManyRelationship.md: \"Many-to-Many tables aren't considered custom tables and don't count toward your custom table allotment.\""},
{id:175,d:5,q:"When creating a many-to-many relationship, what do the From table and To table fields specify?",opts:["From is the parent table and To is the child table", "From is the child table and To is the parent table", "Both must be extensions of Task", "Both must be in the same application scope"],ans:[0],multi:false,src:"docs",exp:"t_CreateAManyToManyRelationship.md: \"In the From table field, specify a parent table... In the To table field, specify a child table.\""},
{id:176,d:5,q:"What is dot-walking used for?",opts:["Accessing fields on a related table from a form, list or script", "Navigating between application menus", "Chaining business rules in order", "Traversing update set hierarchies"],ans:[0],multi:false,src:"docs",exp:"c_DotWalking.md: \"Dot-walking provides access to fields on related tables from a form, list, or script.\""},
{id:177,d:5,q:"What is the documented recommended limit for a dot-walking chain?",opts:["Three levels", "One level", "Five levels", "There is no recommended limit"],ans:[0],multi:false,src:"docs",exp:"c_DotWalking.md: \"The recommended limit for chain length is three levels.\""},
{id:178,d:5,q:"A list must be usable as a related list on another table. What must exist?",opts:["A many-to-many relationship referring to both tables", "A reference field on either table", "A database view", "A dictionary override"],ans:[0],multi:false,src:"docs",exp:"t_CreateAManyToManyRelationship.md: \"For a list to be related to another list, a many-to-many relationship that refers to both tables must exist.\""},
{id:179,d:3,q:"Which quick edit function is available by right-clicking a field in a list?",opts:["Assign to me", "Assign tag", "Create update set", "Run business rule", "Export to PDF"],ans:[0, 1],multi:true,src:"docs",exp:"r_MethodsForListEdits.md quick edit functions: Assign to me, Approve, Reject, Assign tag."},
{id:180,d:5,q:"Every field name on the import set table matches a field name on the target table. Which utility maps them in one step?",opts:["Automatic Mapping — click Auto map matching fields on the Table Transform Map form", "Mapping Assist", "Schema Map", "Field Map scripting"],ans:[0],multi:false,src:"web+docs",exp:"c_MappingOptions.md: \"The simplest mapping method is where all of the field names of the import sets match the names of the fields on the production tables... simply click Auto map matching fields.\" Mapping Assist is the *correction* tool, not the matching one."},
{id:181,d:5,q:"Auto-mapping has matched two fields incorrectly. Which documented utility do you use to correct them?",opts:["Mapping Assist", "Auto map matching fields, run again", "The Schema Map", "A Dictionary Override"],ans:[0],multi:false,src:"docs",exp:"c_MappingOptions.md: \"If there are any discrepancies in terms of how fields were automatically matched, use the mapping assist utility to correct them.\""},
{id:182,d:5,q:"What does the Mapping Assist utility let you do that a plain field map does not?",opts:["Map a single source field to multiple destination fields", "Import from a JDBC source without a data source record", "Coalesce on more than three fields", "Skip the transform step entirely"],ans:[0],multi:false,src:"docs",exp:"c_MappingOptions.md: mapping assist \"makes it possible to map a single source field (field on an import set table) to multiple destination fields (fields on a production table).\""},
{id:183,d:5,q:"You have built a transform map for one import set. What does the documentation say you can do with it?",opts:["Reuse it to map data from another import set to the same table", "Reuse it only within the import set it was created for", "Reuse it against any table on the instance", "Nothing — a transform map is single-use"],ans:[0],multi:false,src:"docs",exp:"c_CreatingNewTransformMaps.md: \"After creating a transform map, you can reuse it to map data from another import set to the same table.\" Note the harvested version of this question claimed reuse on the *same* import set, which the documentation does not say."},
{id:184,d:5,q:"What does every import operation to a production table require?",opts:["At least one transform map associated with an import set", "A scheduled import job", "A coalesce field on the sys_id", "An update set to carry the mapping"],ans:[0],multi:false,src:"docs",exp:"c_ImportDataUsingImportSets.md: \"Every import operation to a production table requires at least one transform map associated with an import set.\""},
{id:185,d:5,q:"In what order are table ACL rules matched?",opts:["The table name, then the parent table name, then any table (*)", "Any table (*), then the parent table name, then the table name", "The parent table name, then the table name, then any table (*)", "Alphabetically by rule name"],ans:[0],multi:false,src:"web+docs",exp:"acl-rule-types.md: \"Table ACL rules are processed in the following order: 1. Match the table name. For example, incident. 2. Match the parent table name. For example, task. 3. Match any table name (*).\""},
{id:186,d:5,q:"A user has passed the table ACL rule on Incident. Which field ACL rule is matched first?",opts:["incident.number — the table and field name", "*.number — any table and the field name", "incident.* — the table and any field", "*.* — any table and any field"],ans:[0],multi:false,src:"docs",exp:"acl-rule-types.md lists the six field steps: incident.number, task.number, *.number, incident.*, task.*, *.* — specific to general."},
{id:187,d:5,q:"A user fails the table ACL rule on Incident but passes a field ACL rule on incident.number. What can they see?",opts:["Nothing — failing the table rule denies every field in the table", "Only the Number field", "Every field except Number", "The whole record, because the field rule grants it"],ans:[0],multi:false,src:"docs",exp:"acl-rule-types.md: \"If a user fails a table ACL rule, the user is denied access to all fields in the table, even if the user passes a field ACL rule.\""},
{id:188,d:5,q:"A user passes the field ACL rule for incident.number. What does the platform do next?",opts:["Stops searching — the first successful field ACL evaluation ends processing at the field level", "Continues evaluating every remaining field rule and takes the most restrictive", "Re-evaluates the table rule", "Applies the *.* rule as a final check"],ans:[0],multi:false,src:"docs",exp:"acl-rule-types.md: \"The first successful field ACL evaluation stops ACL rule processing at the field level.\""},
{id:189,d:5,q:"What is the object name of an ACL rule securing the Major Incident field on the Incident table?",opts:["incident.major_incident", "incident=>major_incident", "Incident.Major_Incident", "incident:*:major_incident"],ans:[0],multi:false,src:"web+docs",exp:"acl-rule-types.md names field rules as table-dot-field, e.g. \"incident.number\"."},
{id:190,d:5,q:"You have been impersonating another user to test their view. What is the documented way back to your own account?",opts:["End Impersonation", "Clear the browser cache", "Restart the browser", "Wait for the session to time out"],ans:[0],multi:false,src:"web",exp:"Platform behaviour, widely agreed but not settled by a page in the docs clone. Treat as a prompt to check."},
{id:191,d:5,q:"Which system property must be set to true for impersonation events to appear in the System Log?",opts:["glide.sys.log_impersonation", "glide.sys.all_impersonation", "glide.impersonation_setting", "glide.user_setting"],ans:[0],multi:false,src:"web",exp:"Harvested; the property name is not in the docs clone, so this is unverified."},
{id:192,d:5,q:"Group records are stored in which table?",opts:["sys_user_group", "sys_group", "sn_user_group", "u_sys_group"],ans:[0],multi:false,src:"web",exp:"Platform fact, uncontroversial but not cited here."},
{id:193,d:5,q:"Which role lets someone authorize a request and nothing else on the platform?",opts:["approver_user", "approval_group", "authorize_user", "reviewer_user"],ans:[0],multi:false,src:"web",exp:"Harvested; not settled by the docs clone."},
{id:194,d:5,q:"What is the object name of an access control rule that applies to the whole Incident table — all rows and all fields?",opts:["incident.None", "incident.all", "incident.*", "incident.rows"],ans:[0],multi:false,src:"web+docs",exp:"exploring-access-control-list.md tabulates a record rule as [incident].[-- None --] with operation create: \"Creating records in the Incident table.\" The bare table plus None is the record rule; incident.* is a *field* rule."},
{id:195,d:5,q:"What is the object name of an access control rule that applies to every field on the Incident table?",opts:["incident.*", "incident.None", "incident.all", "*.incident"],ans:[0],multi:false,src:"docs",exp:"acl-rule-types.md field matching sequence step 4: \"Match the table and any field (*). For example, incident.*.\" This is the pair with Q194 and the one people invert."},
{id:196,d:5,q:"Which may be used to set the permissions an access control rule requires?",opts:["Roles", "Conditional expressions", "A script that sets the answer variable to true or false", "Assignment rules", "User criteria"],ans:[0, 1, 2],multi:true,src:"web+docs",exp:"exploring-access-control-list.md: an access control specifies the object and operation secured, and the permissions required — roles, conditions and a script setting answer. User criteria governs catalog and knowledge, not table ACLs."},
{id:197,d:5,q:"Which system property defines which roles can reach the Personalize Form menu?",opts:["glide.ui.personalize_form_role", "glide.ui.personalize_form.role", "glide.ui.enable_personalize_form.admin", "sys_form_properties.personalize_role"],ans:[0],multi:false,src:"docs",exp:"configure-access-personalize-form-menu.md: \"You can use the glide.ui.personalize_form_role system property to define which roles can access the Personalize Form menu.\" The harvested version of this question keyed glide.ui.personalize_form.role, with a dot, which is not the documented name."},
{id:198,d:5,q:"Which role lets a tester switch between user accounts without logging out and back in?",opts:["impersonator", "incognito", "service_desk", "sys_user"],ans:[0],multi:false,src:"web",exp:"Harvested; the impersonator role is not named in the docs clone."},
{id:199,d:5,q:"A role in ServiceNow is stored where?",opts:["One record in the Role [sys_user_role] table", "One record in the Role [user_sys_role] table", "A set of modules for an application", "A persona used in chat"],ans:[0],multi:false,src:"web",exp:"Harvested; the table name is not confirmed in the docs clone."},
{id:200,d:5,q:"Which table is the base of the CMDB class hierarchy?",opts:["cmdb", "cmdb_ci", "cmdb_rel_ci", "cmdb_ci_hardware"],ans:[0],multi:false,src:"web+docs",exp:"servicenow-platform/index.md: the \"Configuration Item [cmdb_ci] class... extends the Base Configuration Item [cmdb] class.\" cmdb_ci is the one people name, and it is the child."},
{id:201,d:5,q:"A manager needs one report drawing data from two different tables, and dot-walking cannot reach it. What should you build?",opts:["A database view", "A report template", "A custom table holding a copy of both", "A scheduled export to a spreadsheet"],ans:[0],multi:false,src:"web+docs",exp:"c_DatabaseViews.md: \"A database view defines table joins for reporting purposes... can join the Incident table to the Metric Definition and Metric Instance tables... may include fields from any of these three tables.\""},
{id:202,d:5,q:"A report is run against a database view. Which access controls apply?",opts:["The database view's own ACLs if any exist, otherwise the ACLs of the underlying tables", "Always the underlying tables' ACLs; a view cannot carry its own", "Always the view's ACLs; the underlying tables are ignored", "Neither — database views bypass access control"],ans:[0],multi:false,src:"docs",exp:"c_DatabaseViews.md: \"If ACLs exist on the database view itself, those ACLs are evaluated and take precedence. If no database view ACLs exist, the system honors ACLs from the underlying tables.\""},
{id:203,d:5,q:"What distinguishes a base class table from a parent class table?",opts:["A base class table is not extended from another table; a parent class table may itself be extended from one", "A base class table always has tables extended from it; a parent class table never does", "A table can extend a parent or a base, but never both", "There is no difference; the terms are interchangeable"],ans:[0],multi:false,src:"web",exp:"Harvested; the base/parent distinction is used throughout the docs but not defined in one place in this clone."},
{id:204,d:5,q:"You create a custom table named abc in the global scope. What table name does the platform assign?",opts:["u_abc", "abc", "snc_abc", "sys_abc"],ans:[0],multi:false,src:"web",exp:"Harvested; the u_ prefix is not stated in the docs clone."},
{id:205,d:5,q:"What does a schema map show?",opts:["Tables and their relationships, so an admin can see and move around the database schema visually", "The configuration items supporting a business service", "The visual task boards defined for the CMDB", "Which records act as trouble sources for a CI"],ans:[0],multi:false,src:"web",exp:"Harvested; matches how the schema map is used, but no page in the clone defines it."},
{id:206,d:3,q:"What is a formatter?",opts:["A form element used to display information that is not a field in the record", "A set of conditions applied to a table to find and work with data", "A tool that populates fields automatically", "A way to configure which applications appear on the instance"],ans:[0],multi:false,src:"web+docs",exp:"c_Formatters.md, verbatim: \"A formatter is a form element used to display information that is not a field in the record.\""},
{id:207,d:3,q:"What are the main parts of the Form Design interface?",opts:["The page header", "The field navigator", "Form layout", "The field picker", "The dictionary editor"],ans:[0, 1, 2],multi:true,src:"web+docs",exp:"c_FormDesign.md heads exactly three sections: The page header, The field navigator, Form layout. The field navigator is the one holding the Fields and Field Types tabs (see Q160)."},
{id:208,d:3,q:"Which form element shows the list of activities and history on a task form?",opts:["The Activity Formatter", "The Action Stream", "The sidebar", "The History menu"],ans:[0],multi:false,src:"web",exp:"Harvested. The formatter concept is documented (Q206) but the activity formatter is not named in this clone."},
{id:209,d:3,q:"On a form, what is the difference between Insert and Update?",opts:["Insert creates a new record and Update saves changes — both exit the form", "Insert creates a new record and Update saves changes — both stay on the form", "Insert saves and exits; Update saves and stays", "Insert saves and stays; Update saves and exits"],ans:[0],multi:false,src:"web",exp:"Harvested; not settled by a page in the docs clone. Worth knowing because both operations leave the form, which is the part people get wrong."},
{id:210,d:3,q:"A customer wants the Priority field's label changed to their own term across all Task tables. Which right-click options do this?",opts:["Configure Label", "Configure Dictionary", "Configure Display Settings", "Configure Column"],ans:[0, 1],multi:true,src:"web",exp:"Harvested. Contrast with Q211 — the label is the field's *title*, the choice list is its *values*."},
{id:211,d:3,q:"A customer wants the Priority *values* renamed to P1–P4, consistently across every Task table. What do you right-click Priority and select?",opts:["Show Choice List", "Show Options", "Configure Lists", "Configure Options"],ans:[0],multi:false,src:"web",exp:"Harvested. The pair with Q210: renaming a field versus renaming what goes in it."},
{id:212,d:3,q:"You are looking at a list and want to see only the records whose State is In Progress. What is the quickest documented way?",opts:["Right-click the In Progress value in the field and select Show Matching", "Right-click the State column header and select Show > In Progress", "Type In Progress into the list search box", "Click the funnel and rebuild the filter by hand"],ans:[0],multi:false,src:"web+docs",exp:"c_QuickFilters.md: \"To quickly filter a list using a value in a field, right-click in the field and select Show Matching or Filter Out.\""},
{id:213,d:3,q:"You right-click a State value and choose Filter Out. Records with an empty State still appear. Why?",opts:["Quick filter builds [field] [is not] [value] OR [field] [is] [empty], so empty records are deliberately kept", "The list has not refreshed", "Empty values are always excluded from every filter", "The filter needs to be saved before it takes effect"],ans:[0],multi:false,src:"docs",exp:"c_QuickFilters.md: quick filter builds \"[field] [is not] [value] or [field] [is] [empty]. Records that contain empty or null values still display... If you manually create a filter, it does not automatically include the OR condition.\" The same intent gives a different result depending on how the filter was built."},
{id:214,d:3,q:"Which quick filter options does the documentation list for a date field?",opts:["Show Before, Show After, and Filter Out", "Show Matching and Filter Out only", "Show Between and Filter Out", "Sort Ascending and Sort Descending"],ans:[0],multi:false,src:"docs",exp:"c_QuickFilters.md: \"For date fields, choose from Show Before, Show After, and Filter Out.\""},
{id:215,d:3,q:"Where does a quick filter place the condition it adds?",opts:["As the most specific condition of the filter", "As the most general condition of the filter", "It replaces the whole filter", "In a separate saved filter"],ans:[0],multi:false,src:"docs",exp:"c_QuickFilters.md: Show Matching \"adds the condition State = In Progress as the most specific condition of the filter.\" Most specific means rightmost on the breadcrumb — see Q168."},
{id:216,d:3,q:"In the condition builder, which component is always a choice list?",opts:["The operator", "The value", "The match criteria", "The filter criteria"],ans:[0],multi:false,src:"web+docs",exp:"c_ConditionBuilder.md: \"Operator: a choice list based on the field type.\" The value is \"a text entry field or a choice list, depending on field type\", so it is not always one."},
{id:217,d:3,q:"Which feature lets a user filter a list by typing ordinary words instead of building conditions?",opts:["Natural Language Query", "Predictive Intelligence Query", "Auto-suggest Query", "Machine Learning Query"],ans:[0],multi:false,src:"web",exp:"Harvested; natural language query is not covered in the docs clone."},
{id:218,d:3,q:"What is the purpose of a related list?",opts:["To present related records", "To present related fields", "To create a one-to-many relationship", "To dot-walk to a core table"],ans:[0],multi:false,src:"web",exp:"Harvested. Related *records*, not related fields — that is the distractor worth reading twice."},
{id:219,d:1,q:"Which of these does the Application Navigator's History section NOT show?",opts:["UI Pages", "Records", "Lists", "Forms"],ans:[0],multi:false,src:"web",exp:"Harvested. History tracks records, lists and forms you visited, not UI Pages."},
{id:220,d:1,q:"Which icon changes the label and icon of a Favorite?",opts:["The pencil", "The star", "The clock", "The triangle"],ans:[0],multi:false,src:"web",exp:"Harvested. The star creates the favourite; the pencil edits it."},
{id:221,d:1,q:"Typing into the Application Navigator's filter can return which of these?",opts:["Names of applications", "Names of modules", "Favorites", "Titles of dashboard gauges", "The contents of records"],ans:[0, 1, 2],multi:true,src:"web",exp:"Harvested. The navigator filter searches applications, modules and favourites."},
{id:222,d:1,q:"You want hands-on experience with a new ServiceNow application before proposing it. What is the sensible first move?",opts:["Activate the application's plugin on your personal developer instance", "Activate the plugin on the company's production instance", "Read the release notes and decide from those", "Request a sales demo"],ans:[0],multi:false,src:"web",exp:"Harvested, and the only option that does not touch production."},
{id:223,d:2,q:"Which module customises an instance's banner image, text and colours?",opts:["System Properties > Basic Configuration UI16", "System Properties > Branding", "System UI > UI Pages > Branding", "Service Portal > Portals > Branding"],ans:[0],multi:false,src:"web",exp:"Harvested; the module path is not in the docs clone, and menu paths move between releases."},
{id:224,d:2,q:"Where can an admin check which release an instance is running?",opts:["The Stats module", "The Memory Stats module", "The Transactions log", "The System.upgraded table"],ans:[0],multi:false,src:"web",exp:"Harvested; not settled by the docs clone."},
{id:225,d:3,q:"By default, who can see a tag you create?",opts:["Only you — tags default to Me", "Everyone on the instance", "Your groups", "Anyone with the itil role"],ans:[0],multi:false,src:"web+docs",exp:"administering-tags.md: \"By default tags are visible only to the user (Me), but you can share tags with Groups and Users.\""},
{id:226,d:3,q:"Which role is required to create a global tag shared with Everyone?",opts:["tags_admin", "admin", "itil_admin", "personalize_form"],ans:[0],multi:false,src:"docs",exp:"administering-tags.md: \"Users with the tags_admin role are the only users who can create global tags shared with Everyone.\" Pairs with Q225 — sharing widely is role-gated."},
{id:227,d:3,q:"In the Report Designer, which section sets grouping and the calculations run against the data?",opts:["Configure", "Style", "Data", "Format"],ans:[0],multi:false,src:"web",exp:"Harvested. The Report Designer sections are not enumerated in the docs clone."},
{id:228,d:3,q:"In the Report Designer, which section sets colours, titles and legend layout?",opts:["Style", "Format", "Layout", "Configure"],ans:[0],multi:false,src:"web",exp:"Harvested. Pairs with Q227 — Configure decides what the data says, Style decides how it looks."},
{id:229,d:3,q:"You have changed a report and want to see the result without saving it. What do you click?",opts:["Run", "Preview", "Test", "Execute"],ans:[0],multi:false,src:"web",exp:"Harvested. Run shows the result without committing the change."},
{id:230,d:3,q:"You are moving a homepage or dashboard to another instance. What must you remember?",opts:["Add it to the update set manually — it is not captured automatically", "It is added to the current update set automatically", "It cannot be moved by update set at all", "It needs an update set of its own"],ans:[0],multi:false,src:"web+docs",exp:"Consistent with customizations-tracked-update-sets.md: \"Home pages and content pages aren't added to update sets by default. Add pages to the current update set by unloading them.\""},
{id:231,d:3,q:"When creating a notification, what must you define?",opts:["Under what conditions it is sent", "Who receives it", "What its content is", "Which knowledge base it belongs to", "How inactive accounts are handled"],ans:[0, 1, 2],multi:true,src:"web",exp:"Harvested. When, who, what — the three things a notification cannot do without."},
{id:232,d:3,q:"How is the Event Log different from the Event Registry?",opts:["The Event Log holds events that were generated; the Event Registry is the table of event definitions", "They are the same thing shown two ways", "The Event Log is only for integrations", "The Event Registry holds events from the last 24 hours"],ans:[0],multi:false,src:"web",exp:"Harvested. The registry is the definition, the log is the occurrence."},
{id:233,d:3,q:"Which features let you update several records at once?",opts:["The list editor", "Update Selected", "Bulk Record Update", "The Data Remediation dashboard"],ans:[0, 1],multi:true,src:"web",exp:"Harvested. This closes a gap the bank had entirely — nothing tested bulk edits."},
{id:234,d:3,q:"A customer needs Incident numbers read-only on every list and form for every user, and Short Description mandatory on insert across all applications. Which policy type does this?",opts:["Data Policy", "UI Policy", "Data Quality Policy", "Field Criteria Policy"],ans:[0],multi:false,src:"web+docs",exp:"A data policy applies regardless of how data arrives, which is why \"all users, all applications\" points at it rather than a UI policy. See Q107."},
{id:235,d:3,q:"Which entities can receive a task assignment?",opts:["Users", "Groups", "Departments", "Teams"],ans:[0, 1],multi:true,src:"web",exp:"Harvested. Departments and teams are not assignable."},
{id:236,d:3,q:"Which tool holds real-time conversations with logged-in users?",opts:["Connect Chat", "Now Messenger", "User Presence", "Comments"],ans:[0],multi:false,src:"web",exp:"Harvested; Connect Chat is not covered in the docs clone."},
{id:237,d:3,q:"Which framework tests ServiceNow applications?",opts:["The Automated Test Framework (ATF)", "Selenium", "JUnit", "The Test Driven Framework"],ans:[0],multi:false,src:"web",exp:"Harvested."},
{id:238,d:4,q:"On a knowledge base record, which tab defines who may write articles to it?",opts:["Can Contribute", "Can Author", "Can Write", "Cannot Author"],ans:[0],multi:false,src:"web+docs",exp:"Installed-with-km-core.md names the table Who Can Contribute To Knowledge Base [kb_uc_can_contribute_mtom]."},
{id:239,d:4,q:"On a knowledge base record, which tab defines who may NOT write articles to it?",opts:["Cannot Contribute", "Cannot Author", "Read Only", "Cannot Write"],ans:[0],multi:false,src:"web+docs",exp:"Same page: Who Cannot Contribute To Knowledge Base [kb_uc_cannot_contribute_mtom]. The pair with Q238 — contribute, not author or write."},
{id:240,d:4,q:"An article has no user criteria defined. Who can read it?",opts:["All users", "No users", "Only users with the knowledge role", "Only itil users"],ans:[0],multi:false,src:"web+docs",exp:"access-articles-now-mobile.md: \"If no user criteria is defined for an article, all users can read the article.\" Silence opens access rather than closing it, which is the trap."},
{id:241,d:4,q:"A knowledge base's criteria lists Companies: ACME North America, Departments: HR, Groups: ACME Managers, with Match All: Yes. Who gets access?",opts:["Only users who satisfy all three — in ACME North America, in HR, and in the ACME Managers group", "Anyone satisfying any one of the three", "Anyone in ACME North America or HR", "The ACME Managers group regardless of the other two"],ans:[0],multi:false,src:"web",exp:"Harvested. Match All turns the criteria into AND; without it they are OR."},
{id:242,d:4,q:"Which setting lets someone read a knowledge article without logging in?",opts:["The Public setting", "The View All setting", "The ESS role", "The Allow All role"],ans:[0],multi:false,src:"web",exp:"Harvested; not settled by the docs clone."},
{id:243,d:4,q:"What controls the publishing and retiring of knowledge articles?",opts:["Workflows", "Approval policies", "Approval definitions", "The state lifecycle field"],ans:[0],multi:false,src:"web",exp:"Harvested."},
{id:244,d:4,q:"What should an administrator know about Service Catalog variables?",opts:["They are global by default", "They can only be used in record producers", "They can only be used in order guides", "They cannot affect the order price"],ans:[0],multi:false,src:"web",exp:"Harvested; the global default is not stated in the docs clone."},
{id:245,d:4,q:"Which Service Catalog feature organises items into logical groups?",opts:["Categories", "Variable sets", "Sections", "Order guides"],ans:[0],multi:false,src:"web",exp:"Harvested. Categories group items; variable sets group *variables* — see Q246."},
{id:246,d:4,q:"Which field controls the order in which variables appear on a catalog item form?",opts:["The Order field on the Variable", "The Sequence field on the Catalog Item", "The Default Value field on the Catalog Item", "The Choice field on the Variable"],ans:[0],multi:false,src:"web",exp:"Harvested. The Order lives on the variable, not on the item."},
{id:247,d:4,q:"In Flow Designer, where is an action's output stored so later actions can use it?",opts:["In a data pill", "In a data element", "In a field value", "In a data trigger"],ans:[0],multi:false,src:"web",exp:"Harvested. The data pill is how Flow Designer passes values between actions."},
{id:248,d:4,q:"In Flow Designer, what is an IntegrationHub integration with a third-party API called?",opts:["A spoke", "An action", "A connection", "An integration step"],ans:[0],multi:false,src:"web",exp:"Harvested. A spoke is the packaged integration; an action is a step inside a flow."},
{id:249,d:4,q:"Which of these are frequently used Flow Designer core actions?",opts:["Create Record", "Look Up Record", "Ask for Approval", "Look for Update", "Wait for Match"],ans:[0, 1, 2],multi:true,src:"web",exp:"Harvested."},
{id:250,d:5,q:"What are the three key tables of an enterprise CMDB?",opts:["cmdb", "cmdb_ci", "cmdb_rel_ci", "sn_cmdb", "cmdb_bak"],ans:[0, 1, 2],multi:true,src:"web+docs",exp:"servicenow-platform/index.md establishes cmdb as the base class and cmdb_ci as its extension (see Q200); cmdb_rel_ci holds the relationships behind the dependency view."},
{id:251,d:5,q:"Which tool graphically shows a configuration item and its relationships to other CIs?",opts:["Dependency View", "Schema Map", "Database View", "Transform Map"],ans:[0],multi:false,src:"web",exp:"Harvested. The schema map shows *tables*; the dependency view shows *CIs* — see Q205."},
{id:252,d:5,q:"What are the primary operations performed against tables in the platform?",opts:["Create, Read, Write, Delete", "Create, Read, Update, Delete", "Create, Read, Upload, Delete", "Capture, Rate, Write, Develop"],ans:[0],multi:false,src:"web",exp:"Harvested."},
{id:253,d:5,q:"A user can only see Self Service and needs to work on task records. What are the likely causes?",opts:["Their account does not have the itil role", "Their account is in no group that carries the itil role", "Their account failed LDAP authentication", "Their manager has not approved the account"],ans:[0, 1],multi:true,src:"web",exp:"Harvested. Both routes to the itil role, direct or through a group, are worth knowing — see Q257."},
{id:254,d:5,q:"What protects one application's data from being reached by another application on the same instance?",opts:["Application scope", "Access control rules", "Assignment rules", "The admin center"],ans:[0],multi:false,src:"web",exp:"Harvested. Scope is the application boundary; ACLs are the record boundary."},
{id:255,d:5,q:"Which are valid user authentication methods?",opts:["Local database", "LDAP", "SSO", "XML feed", "FTP authentication"],ans:[0, 1, 2],multi:true,src:"web",exp:"Harvested."},
{id:256,d:5,q:"What is the documented best practice before running a data import?",opts:["Plan time to remove obsolete or inaccurate data first", "Use one very large import set rather than several", "Adjust the transform maps after loading", "Create a new import set table for every load"],ans:[0],multi:false,src:"web+docs",exp:"Consistent with c_ImportSetsKeyConcepts.md: \"Do not import data in extremely large chunks. Creating an extremely large import set can cause delays and system outages.\""},
{id:257,d:5,q:"What is best practice for users, groups and roles?",opts:["Assign roles to groups", "Add users to groups", "Assign roles directly to users", "Never assign roles to groups"],ans:[0, 1],multi:true,src:"web",exp:"Harvested. Roles to groups, users to groups — never roles straight onto users."},
{id:258,d:6,q:"Which field on a UI Policy makes it apply to every form view?",opts:["Global", "Inherit", "On load", "Reverse if false"],ans:[0],multi:false,src:"web+docs",exp:"t_CreateAUIPolicy.md: Global is the \"option for specifying whether the UI policy applies to all form views... By default, the Global UI policy applies to all form views.\""},
{id:259,d:6,q:"A UI Policy has Global cleared and the View field left blank. Which view does it apply to?",opts:["The default view", "Every view", "No view — it is inactive", "The itil view"],ans:[0],multi:false,src:"docs",exp:"t_CreateAUIPolicy.md: \"If Global is not selected and the View field is left blank, the script applies the default view.\" The pair with Q258."},
{id:260,d:6,q:"Which are examples of UI Actions on lists?",opts:["List Links", "List Buttons", "List Context Menu", "List Override", "List Control"],ans:[0, 1, 2],multi:true,src:"web",exp:"Harvested. Contrast the form set: Form Buttons, Form Context Menu, Form Links."},
{id:261,d:6,q:"How are workflows moved between instances?",opts:["In update sets", "In transform maps", "In application sets", "They cannot be moved"],ans:[0],multi:false,src:"web",exp:"Harvested. Workflows are configuration, so they travel the configuration route."}
];
